package com.shopsphere;
import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import java.math.BigDecimal;import java.util.*;
class OrderPricingSecurityTest {
 @Test void ignoresForgedPriceNameSkuDiscountAndDelivery(){var inventory=new OrderServiceTest.Inventory();var repo=new OrderRepository.InMemory();var id=UUID.randomUUID();var service=new OrderService(repo,inventory,new OrderIdempotencyStore.InMemory(),i->new ProductPricingGateway.PricedProduct(id,"Real phone","REAL-SKU",BigDecimal.valueOf(999),true));var address=new OrderDtos.AddressRequest("QA","Street",null,"City","State","560001","India","9999999999");var request=new OrderDtos.Create(UUID.randomUUID(),List.of(new OrderDtos.Item(id,"Forged","FAKE",BigDecimal.ONE,1)),BigDecimal.valueOf(999999),BigDecimal.valueOf(-100),address);var order=service.create("tamper-proof",request);assertEquals(BigDecimal.valueOf(999),order.items().getFirst().unitPrice());assertEquals("Real phone",order.items().getFirst().productName());assertEquals("REAL-SKU",order.items().getFirst().sku());assertEquals(BigDecimal.ZERO,order.discount());assertEquals(BigDecimal.valueOf(99),order.deliveryFee());assertEquals(BigDecimal.valueOf(1098),order.totalAmount());}
 @Test void failedPricingReleasesClaimWithoutReservingStock(){var inventory=new OrderServiceTest.Inventory();var idem=new OrderIdempotencyStore.InMemory();var service=new OrderService(new OrderRepository.InMemory(),inventory,idem,i->{throw new ProductPricingException("offline");});var request=new OrderDtos.Create(UUID.randomUUID(),List.of(new OrderDtos.Item(UUID.randomUUID(),null,null,null,1)),null,null,new OrderDtos.AddressRequest("QA","Street",null,"City","State","560001","India","9999999999"));assertThrows(ProductPricingException.class,()->service.create("retryable",request));assertThrows(ProductPricingException.class,()->service.create("retryable",request));assertEquals(0,inventory.reserved);}
}
